ALTER TABLE access_profiles ADD COLUMN system_role text CHECK(system_role IN ('owner','admin','supervisor','member'));
CREATE UNIQUE INDEX access_profiles_system_role ON access_profiles(tenant_id,system_role) WHERE system_role IS NOT NULL;
ALTER TABLE tenant_members ADD COLUMN custom_permissions text[];
COMMENT ON COLUMN tenant_members.custom_permissions IS 'Optional personal permission snapshot, isolated to this membership. NULL inherits the assigned profile/role.';
-- Preserve all existing grants while expanding formerly bundled actions.
UPDATE access_profiles SET permissions=ARRAY(SELECT DISTINCT permission FROM unnest(permissions || CASE WHEN 'mail.organize'=ANY(permissions) THEN ARRAY['mail.move','mail.delete','mail.restore','mail.flag'] ELSE '{}'::text[] END || CASE WHEN 'contacts'=ANY(permissions) THEN ARRAY['contacts.create','contacts.edit'] ELSE '{}'::text[] END) permission);
CREATE FUNCTION seed_system_access_profiles() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 INSERT INTO access_profiles(tenant_id,name,description,permissions,system_role) VALUES (NEW.id,'Proprietário','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','contacts.delete','chat','calendar','reminders','schedules','reports','users.view','users.invite','users.manage','profiles.manage','audit.view','audit.content','mailboxes.manage','company.manage','integrations','signatures','labels','rules','archives']::text[],'owner'),
(NEW.id,'Administrador','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','contacts.delete','chat','calendar','reminders','schedules','reports','users.view','users.invite','users.manage','profiles.manage','audit.view','audit.content','mailboxes.manage','company.manage','integrations','signatures','labels','rules','archives']::text[],'admin'),
(NEW.id,'Supervisor','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','chat','calendar','reminders','schedules','reports','integrations','signatures','labels','rules','users.view','audit.view','contacts.delete']::text[],'supervisor'),
(NEW.id,'Membro','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','chat','calendar','reminders','schedules','reports','integrations','signatures','labels','rules']::text[],'member') ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;
CREATE TRIGGER tenants_system_access_profiles AFTER INSERT ON tenants FOR EACH ROW EXECUTE FUNCTION seed_system_access_profiles();
INSERT INTO access_profiles(tenant_id,name,description,permissions,system_role) SELECT id,'Proprietário','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','contacts.delete','chat','calendar','reminders','schedules','reports','users.view','users.invite','users.manage','profiles.manage','audit.view','audit.content','mailboxes.manage','company.manage','integrations','signatures','labels','rules','archives']::text[],'owner' FROM tenants ON CONFLICT DO NOTHING;
INSERT INTO access_profiles(tenant_id,name,description,permissions,system_role) SELECT id,'Administrador','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','contacts.delete','chat','calendar','reminders','schedules','reports','users.view','users.invite','users.manage','profiles.manage','audit.view','audit.content','mailboxes.manage','company.manage','integrations','signatures','labels','rules','archives']::text[],'admin' FROM tenants ON CONFLICT DO NOTHING;
INSERT INTO access_profiles(tenant_id,name,description,permissions,system_role) SELECT id,'Supervisor','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','chat','calendar','reminders','schedules','reports','integrations','signatures','labels','rules','users.view','audit.view','contacts.delete']::text[],'supervisor' FROM tenants ON CONFLICT DO NOTHING;
INSERT INTO access_profiles(tenant_id,name,description,permissions,system_role) SELECT id,'Membro','Perfil padrão do sistema. Duplique para criar uma função personalizada.',ARRAY['mail','mail.send','mail.organize','mail.move','mail.delete','mail.restore','mail.flag','contacts','contacts.create','contacts.edit','chat','calendar','reminders','schedules','reports','integrations','signatures','labels','rules']::text[],'member' FROM tenants ON CONFLICT DO NOTHING;
